# PolyQuintic(f): the special functions of a depressed monic quintic f (a
# dpoly or an expression in its generator)
.pq_zeta <- function() list(
  .add(list(Rational(-1, 4), .div(.sqrt(.int(5)), .int(4)), .mul(list(S_I, .sqrt(.add(list(.div(.sqrt(.int(5)), .int(8)), Rational(5, 8)))))))),
  .add(list(.div(.neg(.sqrt(.int(5))), .int(4)), Rational(-1, 4), .mul(list(S_I, .sqrt(.add(list(.div(.neg(.sqrt(.int(5))), .int(8)), Rational(5, 8)))))))),
  .add(list(.div(.neg(.sqrt(.int(5))), .int(4)), Rational(-1, 4), .neg(.mul(list(S_I, .sqrt(.add(list(.div(.neg(.sqrt(.int(5))), .int(8)), Rational(5, 8))))))))),
  .add(list(Rational(-1, 4), .div(.sqrt(.int(5)), .int(4)), .neg(.mul(list(S_I, .sqrt(.add(list(.div(.sqrt(.int(5)), .int(8)), Rational(5, 8))))))))))

#' Solvable quintics
#'
#' `PolyQuintic(f)` holds the special functions of SymPy's
#' `sympy.polys.polyquinticconst.PolyQuintic` for a quintic
#' `x^5 + p*x^3 + q*x^2 + r*x + s` with rational coefficients: `$f20` (the
#' resolvent sextic as a polynomial in `x`), `$F`, `$zeta` (the primitive
#' fifth roots of unity), the coefficient lists `$b`, `$o`, `$a` and `$c`
#' of SymPy's properties of the same names, and the functions `$l0(theta)`, `$T(theta, d)`,
#' `$order(theta, d)` and `$uv(theta, d)`. `roots_quintic(f)` returns the five
#' roots of a solvable irreducible quintic in radicals, or an empty list
#' when the quintic is reducible or not solvable; `roots(f, quintics = TRUE)`
#' uses it.
#'
#' @param f A quintic polynomial expression (or `Poly`) in one variable.
#' @return `PolyQuintic()` returns an object of class `PolyQuintic`;
#'   `roots_quintic()` a list of expressions.
#' @examples
#' x <- Symbol("x")
#' q <- PolyQuintic(x^5 - 5 * x + 12)
#' q$f20
#' length(roots_quintic(x^5 - 5 * x + 12))
#' @export
PolyQuintic <- function(f) {
  cf <- .pq_coeffs(f)
  x <- cf$x
  v <- lapply(cf$c[3:6], function(z) gmp::as.bigq(z$value))
  structure(list(p = cf$c[[3L]], q = cf$c[[4L]], r = cf$c[[5L]], s = cf$c[[6L]], pv = v, x = x), class = "PolyQuintic")
}
.pq_coeffs <- function(f) {
  if (inherits(f, "dpoly")) return(list(c = .pr_all_coeffs(f), x = f$x))
  if (inherits(f, "Poly")) return(list(c = all_coeffs(f), x = f$gens[[1L]]))
  f <- as_sym(f)
  x <- free_symbols(f)[[1L]]
  list(c = .coeff_list(expand(f), x), x = x)
}
.pq_call <- function(Q, fn) do.call(fn, unname(Q$pv))
.pq_num <- function(v) make_rational(gmp::as.bigq(v))
.pq_polyeval <- function(cs, theta) {
  # Poly(cs, x).eval(theta), cs leading first, exact
  th <- gmp::as.bigq(theta$value)
  v <- gmp::as.bigq(0)
  for (c in cs) v <- v * th + gmp::as.bigq(c)
  make_rational(v)
}
#' @rdname PolyQuintic
#' @param x A `PolyQuintic` object.
#' @param name The name of a field or method.
#' @export
`$.PolyQuintic` <- function(x, name) {
  Q <- unclass(x)
  switch(name,
    f20 = {
      cs <- .pq_call(Q, .pq_f20)
      X <- Symbol("x")
      Poly(.add(lapply(seq_along(cs), function(i) .mul(list(make_rational(gmp::as.bigq(cs[[i]])), .pow(X, .int(length(cs) - i)))))), X)
    },
    F = make_rational(gmp::as.bigq(.pq_call(Q, .pq_F))),
    zeta = .pq_zeta(),
    b = .pytuple(lapply(.pq_call(Q, .pq_b), function(z) lapply(z, .pq_num))),
    o = lapply(.pq_call(Q, .pq_o), .pq_num),
    a = lapply(.pq_call(Q, .pq_a), .pq_num),
    c = lapply(.pq_call(Q, .pq_c), .pq_num),
    l0 = function(theta) .div(.pq_polyeval(.pq_call(Q, .pq_a), as_sym(theta)), x$F),
    T = function(theta, d) {
      theta <- as_sym(theta); d <- as_sym(d)
      b <- .pq_call(Q, .pq_b); F <- x$F
      list(S_Zero,
           .neg(.div(.pq_polyeval(b[[2L]], theta), .mul(list(S_Two, F)))),
           .div(.pq_polyeval(b[[3L]], theta), .mul(list(S_Two, d, F))),
           .div(.pq_polyeval(b[[4L]], theta), .mul(list(S_Two, F))),
           .div(.pq_polyeval(b[[5L]], theta), .mul(list(S_Two, d, F))))
    },
    order = function(theta, d) N(.div(.pq_polyeval(.pq_call(Q, .pq_o), as_sym(theta)), .mul(list(as_sym(d), x$F)))),
    uv = function(theta, d) {
      u <- .mul(list(Q$q, Rational(-25, 2)))
      v <- .div(.pq_polyeval(.pq_call(Q, .pq_c), as_sym(theta)), .mul(list(S_Two, as_sym(d), x$F)))
      list(N(u), N(v))
    },
    Q[[name]])
}
#' @rdname PolyQuintic
#' @param ... Unused.
#' @export
print.PolyQuintic <- function(x, ...) {
  cat("PolyQuintic(p = ", .str(unclass(x)$p), ", q = ", .str(unclass(x)$q), ", r = ", .str(unclass(x)$r),
      ", s = ", .str(unclass(x)$s), ")\n", sep = "")
  invisible(x)
}

.quintic_simplify <- function(e) together(cancel(powsimp(e)))
# comp(z, 0, tol): |z| <= tol
.pq_comp0 <- function(z, tol = 1e-10) base::Mod(.neval(as_sym(z), list())) <= tol

#' @rdname PolyQuintic
#' @export
roots_quintic <- function(f) {
  cf <- .pq_coeffs(f)
  x <- cf$x
  co <- cf$c
  if (length(co) != 6L || !all(vapply(co, is_exact_number, NA))) return(list())
  coeff_5 <- co[[1L]]; coeff_4 <- co[[2L]]; p_ <- co[[3L]]; q_ <- co[[4L]]; r_ <- co[[5L]]; s_ <- co[[6L]]
  if (!is_one_num(coeff_5)) {
    co <- lapply(co, function(z) .div(z, coeff_5))
    coeff_4 <- co[[2L]]; p_ <- co[[3L]]; q_ <- co[[4L]]; r_ <- co[[5L]]; s_ <- co[[6L]]
  }
  q5 <- function(a) make_rational(a)
  if (!is_zero_num(coeff_4)) {
    c4 <- gmp::as.bigq(coeff_4$value); P <- gmp::as.bigq(p_$value); Qv <- gmp::as.bigq(q_$value)
    R <- gmp::as.bigq(r_$value); Sv <- gmp::as.bigq(s_$value)
    p <- q5(P - 2 * c4 * c4 / 5)
    q <- q5(Qv - 3 * c4 * P / 5 + 4 * c4^3 / 25)
    r <- q5(R - 2 * c4 * Qv / 5 + 3 * c4^2 * P / 25 - 3 * c4^4 / 125)
    s <- q5(Sv - c4 * R / 5 + c4^2 * Qv / 25 - c4^3 * P / 125 + 4 * c4^5 / 3125)
  } else {
    p <- p_; q <- q_; r <- r_; s <- s_
  }
  fe <- .add(list(.pow(x, .int(5)), .mul(list(p, .pow(x, .int(3)))), .mul(list(q, .pow(x, S_Two))), .mul(list(r, x)), s))
  quintic <- PolyQuintic(fe)
  fl <- factor_list(fe, x)
  if (!(length(fl$factors) == 1L && identical(as.integer(fl$factors[[1L]][[2L]]), 1L))) return(list())
  f20 <- quintic$f20
  X <- Symbol("x")
  f20l <- factor_list(as_expr(f20), X)
  if (length(f20l$factors) == 1L && identical(as.integer(f20l$factors[[1L]][[2L]]), 1L)) return(list())
  theta <- NULL
  for (fc in f20l$factors) {
    cl <- .coeff_list(expand(fc[[1L]]), X)
    if (length(cl) == 2L) { theta <- .div(.neg(cl[[2L]]), cl[[1L]]); break }
  }
  d <- discriminant(fe, x)
  delta <- .sqrt(d)
  zeta <- quintic$zeta
  zeta1 <- zeta[[1L]]; zeta2 <- zeta[[2L]]; zeta3 <- zeta[[3L]]; zeta4 <- zeta[[4L]]
  T <- quintic$T(theta, d)
  tol <- 1e-10
  alpha <- .add(list(T[[2L]], .mul(list(T[[3L]], delta))))
  alpha_bar <- .sub(T[[2L]], .mul(list(T[[3L]], delta)))
  beta <- .add(list(T[[4L]], .mul(list(T[[5L]], delta))))
  beta_bar <- .sub(T[[4L]], .mul(list(T[[5L]], delta)))
  disc <- .sub(.sq(alpha), .mul(list(.int(4), beta)))
  disc_bar <- .sub(.sq(alpha_bar), .mul(list(.int(4), beta_bar)))
  l0 <- quintic$l0(theta)
  l1 <- .quintic_simplify(.div(.add(list(.neg(alpha), .sqrt(disc))), S_Two))
  l4 <- .quintic_simplify(.div(.sub(.neg(alpha), .sqrt(disc)), S_Two))
  l2 <- .quintic_simplify(.div(.add(list(.neg(alpha_bar), .sqrt(disc_bar))), S_Two))
  l3 <- .quintic_simplify(.div(.sub(.neg(alpha_bar), .sqrt(disc_bar)), S_Two))
  order <- quintic$order(theta, d)
  nv <- function(e) .neval(as_sym(e), list())
  test <- nv(order) * nv(delta) - (nv(l1) - nv(l4)) * (nv(l2) - nv(l3))
  if (!(base::Mod(test) <= tol)) { tmp <- l2; l2 <- l3; l3 <- tmp }
  lin <- function(a, b, c, d, e) .add(list(a, .mul(list(b, zeta1)), .mul(list(c, zeta2)), .mul(list(d, zeta3)), .mul(list(e, zeta4))))
  R1 <- .quintic_simplify(lin(l0, l1, l2, l3, l4))
  R2 <- .quintic_simplify(lin(l0, l3, l1, l4, l2))
  R3 <- .quintic_simplify(lin(l0, l2, l4, l1, l3))
  R4 <- .quintic_simplify(lin(l0, l4, l3, l2, l1))
  z <- Symbol("z")
  x0 <- .pow(z, Rational(1, 5)); x1 <- .sqrt(S_Two); x2 <- .sqrt(.int(5)); x3 <- .sqrt(.sub(.int(5), x2))
  x4 <- .mul(list(S_I, x2)); x5 <- .add(list(x4, S_I)); x6 <- .div(.mul(list(S_I, x0)), .int(4))
  x7 <- .mul(list(x1, .sqrt(.add(list(x2, .int(5))))))
  sol <- list(x0, .neg(.mul(list(x6, .sub(.mul(list(x1, x3)), x5)))), .mul(list(x6, .add(list(.mul(list(x1, x3)), x5)))),
              .neg(.mul(list(x6, .add(list(x4, x7, .neg(S_I)))))), .mul(list(x6, .add(list(.neg(x4), x7, S_I)))))
  Rs <- lapply(list(R1, R2, R3, R4), function(Ri) { ri <- .as_real_imag(Ri); .add(list(ri[[1L]], .mul(list(S_I, ri[[2L]])))) })
  Res <- lapply(Rs, function(Ri) lapply(sol, function(s1) .quintic_simplify(xreplace(s1, list(list(z, Ri))))))
  Res_n <- lapply(Res, function(row) lapply(row, nv))
  Res <- lapply(Res, function(row) lapply(row, .quintic_simplify))
  r1 <- Res[[1L]][[1L]]; r1_n <- Res_n[[1L]][[1L]]
  r4 <- NULL
  for (i in 1:5) if (abs(Im(r1_n * Res_n[[4L]][[i]])) <= tol) { r4 <- Res[[4L]][[i]]; break }
  uv <- quintic$uv(theta, d)
  testplus <- nv(uv[[1L]]) + nv(uv[[2L]]) * nv(delta) * sqrt(5)
  testminus <- nv(uv[[1L]]) - nv(uv[[2L]]) * nv(delta) * sqrt(5)
  r4_n <- nv(r4)
  r2 <- r3 <- NULL
  for (i in 1:5) {
    r2temp_n <- Res_n[[2L]][[i]]
    for (j in 1:5) {
      r3temp_n <- Res_n[[3L]][[j]]
      if (base::Mod(r1_n * r2temp_n^2 + r4_n * r3temp_n^2 - testplus) <= tol &&
          base::Mod(r3temp_n * r1_n^2 + r2temp_n * r4_n^2 - testminus) <= tol) {
        r2 <- Res[[2L]][[i]]; r3 <- Res[[3L]][[j]]
        break
      }
    }
    if (!is.null(r2)) break
  }
  if (is.null(r2)) return(list())
  five <- .int(5)
  result <- list(
    .div(.add(list(r1, r2, r3, r4)), five),
    .div(.add(list(.mul(list(r1, zeta4)), .mul(list(r2, zeta3)), .mul(list(r3, zeta2)), .mul(list(r4, zeta1)))), five),
    .div(.add(list(.mul(list(r1, zeta3)), .mul(list(r2, zeta1)), .mul(list(r3, zeta4)), .mul(list(r4, zeta2)))), five),
    .div(.add(list(.mul(list(r1, zeta2)), .mul(list(r2, zeta4)), .mul(list(r3, zeta1)), .mul(list(r4, zeta3)))), five),
    .div(.add(list(.mul(list(r1, zeta1)), .mul(list(r2, zeta2)), .mul(list(r3, zeta3)), .mul(list(r4, zeta4)))), five))
  saw <- character()
  for (rr in result) {
    k <- N(rr, 2)$key
    if (k %in% saw) return(list())
    saw <- c(saw, k)
  }
  if (!is_zero_num(coeff_4)) result <- lapply(result, function(z1) .sub(z1, .div(coeff_4, five)))
  result
}
